contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount) public payable {
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        c.addToBalance{value: depositAmount}();
        uint before = c.getBalance(address(this));
        uint contractBalBefore = address(c).balance;

        c.withdrawBalance();

        uint afterBal = c.getBalance(address(this));
        uint contractBalAfter = address(c).balance;

        assert(afterBal == 0 && contractBalBefore - contractBalAfter == before && before == depositAmount);
    }

    receive() external payable {}
}

